import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.BVA38fkC.js";var i=JSON.parse(`{"title":"Simulation lifecycle","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/docs/SIMULATION-LIFECYCLE.html"}],["meta",{"property":"og:title","content":"Simulation lifecycle | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/docs/SIMULATION-LIFECYCLE.html"}],["meta",{"name":"twitter:title","content":"Simulation lifecycle | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"SIMULATION-LIFECYCLE.md","filePath":"SIMULATION-LIFECYCLE.md","lastUpdated":1793947772000}`),a={name:`SIMULATION-LIFECYCLE.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="simulation-lifecycle" tabindex="-1">Simulation lifecycle <a class="header-anchor" href="#simulation-lifecycle" aria-label="Permalink to “Simulation lifecycle”">​</a></h1><p>The simulation layer owns actual execution and finalisation. Strategies own investment decisions and strategy-specific hypothetical planning; they do not process the authoritative event timeline or mutate actual account balances.</p><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to “Ownership”">​</a></h2><ol><li>The engine normalises and validates the input configuration and creates a <code>SimulationContext</code>.</li><li>The engine creates <code>SimulationRuntime</code> with authoritative account state and the actual event timeline.</li><li>The selected strategy receives an isolated context view and creates a planning session.</li><li>The engine advances the runtime to the next actual event date or requested wait boundary. The runtime applies inflows, FD cash flows and maturities, then settles due outflows.</li><li>The strategy returns an immutable, revision-bound <code>SPLIT</code>, <code>CONSOLIDATE</code>, <code>CARRY</code>, <code>BATCH</code>, <code>WAIT</code> or <code>COMPLETE</code> signal. The runtime validates the complete decision before committing balance or ledger mutations.</li><li>The runtime builds the unfinished result when the scoped date range completes or the strategy session completes.</li><li>The engine adds the simulation-start marker and invokes finalisation exactly once.</li><li>Finalisation performs the single simulation-wide consolidation sweep, records remaining idle balances and marks the result finalised.</li></ol><p>A stale signal, malformed plan, invalid account reference, invalid transfer or ineligible booking is rejected before the decision&#39;s staged mutations are committed. Same-date GSS decisions use an atomic batch so a later invalid sub-action cannot leave earlier sub-actions partially executed.</p><h2 id="strategy-planning-boundaries" tabindex="-1">Strategy planning boundaries <a class="header-anchor" href="#strategy-planning-boundaries" aria-label="Permalink to “Strategy planning boundaries”">​</a></h2><ul><li><strong>Absolute R</strong> retains exhaustive scoped branch-and-bound, terminal-value scoring, admissible bounds and exhaustive local combinations.</li><li><strong>Absolute R+</strong> retains bounded scoped beam search, local-branch ordering, root diversity and configured search limits.</li><li><strong>Greedy</strong> evaluates the current immutable account snapshot with its existing SPLIT / CONSOLIDATE / CARRY planner.</li><li><strong>GSS</strong> retains its recursive planner, forecast contraction, ancestor reforecasting and interim-plan exploration within the requested scoped horizon.</li></ul><p>Hypothetical strategy projections may use local copies of financial and event models to evaluate future choices. Those projections are not the authoritative simulation ledger and are never returned as the actual result.</p><h2 id="finalisation-invariants" tabindex="-1">Finalisation invariants <a class="header-anchor" href="#finalisation-invariants" aria-label="Permalink to “Finalisation invariants”">​</a></h2><ul><li>Exactly one finalisation pass per completed <code>SimulationEngine.run()</code>.</li><li>The scoped run performs one final consolidation sweep after the requested date range and strategy session complete.</li><li>Recursive planning frames, search branches, waits and hypothetical projections are not finalisation boundaries.</li><li>Strategies do not create the actual final result or final sweep events.</li><li>Final sweep fees are included in total transfer fees.</li></ul><h2 id="goal-mode-development-boundary" tabindex="-1">Goal-mode development boundary <a class="header-anchor" href="#goal-mode-development-boundary" aria-label="Permalink to “Goal-mode development boundary”">​</a></h2><p>Goal-runtime support remains in the internal engine and its direct unit tests while the user-facing mode is disabled. Public configuration validation and the browser do not expose goal mode. The planned future optimiser is Absolute R only; no Goal-specific optimisation branches should be added to Greedy, GSS or Absolute R+.</p>`,12)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};